initJs:
function(container, apiUrl, tables) {
  let selectedProductId = null;
  let currentPrediction = null;

  // 店舗データを取得してドロップダウンに設定
  function loadStores() {
    window.aivicApi.list(1).then(stores => {
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      if (stores) {
        stores.filter(s => s.有効フラグ).forEach(store => {
          storeSelect.innerHTML += `<option value="${store.id}">${store.店舗名}</option>`;
        });
      }
    });
  }

  // 商品データを取得してテーブルに表示
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');
    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" class="muted" style="text-align:center;">商品が見つかりません</td></tr>';
      return;
    }

    tbody.innerHTML = products.map(product => `
      <tr data-id="${product.id}">
        <td><input type="radio" name="product-select" value="${product.id}" class="product-radio"></td>
        <td>${product.商品コード || ''}</td>
        <td>${product.商品名|| ''}</td>
        <td>${product.商品カテゴリID || ''}</td>
        <td>¥${(product.単価 || 0).toLocaleString()}</td>
        <td>${product.発注単位 || 1}</td>
      </tr>
    `).join('');
  }

  // 商品検索・絞り込み
  function filterProducts() {
    const storeId = container.querySelector('#store-select').value;
    const categoryId = container.querySelector('#category-select').value;
    const searchKeyword = container.querySelector('#product-search').value.toLowerCase();

    if (!storeId) {
      showError('store-error', '店舗を選択してください');
      return;
    }

    window.aivicApi.list(2).then(products => {
      if (!products) return;

      let filtered = products.filter(p => p.有効フラグ);

      if (categoryId) {
        filtered = filtered.filter(p => p.商品カテゴリID === categoryId);
      }

      if (searchKeyword) {
        filtered = filtered.filter(p => 
          (p.商品名 || '').toLowerCase().includes(searchKeyword) ||
          (p.商品コード || '').toLowerCase().includes(searchKeyword)
        );
      }

      renderProducts(filtered);
      clearError('store-error');
    });
  }

  // AI予測実行
  function executeAIPrediction() {
    const storeId = container.querySelector('#store-select').value;
    const periodStart = container.querySelector('#period-start').value;
    const periodEnd = container.querySelector('#period-end').value;

    // バリデーション
    if (!storeId) {
      showError('store-error', '店舗を選択してください');
      return;
    }
    if (!periodStart) {
      showError('period-start-error', '対象期間開始日を設定してください');
      return;
    }
    if (!periodEnd) {
      showError('period-end-error', '対象期間終了日を設定してください');
      return;
    }
    if (!selectedProductId) {
      alert('商品を選択してください');
      return;
    }

    clearAllErrors();

    // 予測結果を取得（模擬データ）
    window.aivicApi.list(8).then(predictions => {
      if (predictions) {
        const prediction = predictions.find(p => 
          p.店舗ID === storeId && p.商品ID === selectedProductId
        );

        if (prediction) {
          currentPrediction = prediction;
          displayPredictionResults(prediction);
        } else {
          // 模擬予測データを生成
          const mockPrediction = {
            予測数量: Math.floor(Math.random() * 100) + 50,
            予測精度: Math.floor(Math.random() * 30) + 70,
            推奨発注数量: Math.floor(Math.random() * 80) + 40
          };
          currentPrediction = mockPrediction;
          displayPredictionResults(mockPrediction);
        }
      }
    });
  }

  // 予測結果表示
  function displayPredictionResults(prediction) {
    container.querySelector('.prediction-placeholder').classList.add('hidden');
    container.querySelector('#prediction-results').classList.remove('hidden');

    container.querySelector('#predicted-quantity').textContent = `${prediction.予測数量 || 0}個`;
    container.querySelector('#prediction-accuracy').textContent = `${prediction.予測精度 || 0}%`;
    container.querySelector('#recommended-quantity').textContent = `${prediction.推奨発注数量 || 0}個`;
    container.querySelector('#ai-recommended').textContent = `${prediction.推奨発注数量 || 0}個`;
    container.querySelector('#manual-adjustment').placeholder = `${prediction.推奨発注数量 || 0}`;
  }

  // 発注量計算実行
  function calculateOrderQuantity() {
    const currentStock = parseInt(container.querySelector('#current-stock').value) || 0;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 0;
    const weatherImpact = parseInt(container.querySelector('#weather-impact').value) || 100;
    const eventImpact = parseInt(container.querySelector('#event-impact').value) || 100;
    const seasonalFactor = parseFloat(container.querySelector('#seasonal-factor').value) || 1.0;
    const manualAdjustment = parseInt(container.querySelector('#manual-adjustment').value);

    // バリデーション
    if (currentStock < 0) {
      showError('stock-error', '在庫数は0以上の値を入力してください');
      return;
    }
    if (safetyStock < 0) {
      showError('safety-error', '安全在庫は0以上の値を入力してください');
      return;
    }
    if (leadTime < 1 || leadTime > 365) {
      showError('leadtime-error', 'リードタイムは1-365日の範囲で入力してください');
      return;
    }
    if (seasonalFactor < 0.01 || seasonalFactor > 9.99) {
      showError('seasonal-error', '季節補正係数は0.01-9.99の範囲で入力してください');
      return;
    }
    if (manualAdjustment !== null && !isNaN(manualAdjustment) && manualAdjustment < 0) {
      showError('manual-error', '発注量は0以上の値を入力してください');
      return;
    }

    clearAllErrors();

    if (!currentPrediction) {
      alert('AI予測を実行してください');
      return;
    }

    // 発注量計算ロジック
    const baseDemand = currentPrediction.推奨発注数量 || 0;
    const adjustedDemand = baseDemand * (weatherImpact / 100) * (eventImpact / 100) * seasonalFactor;
    const calculatedQuantity = Math.max(0, adjustedDemand + safetyStock - currentStock);

    const finalQuantity = !isNaN(manualAdjustment) ? manualAdjustment : Math.ceil(calculatedQuantity);

    container.querySelector('#final-quantity').textContent = `${finalQuantity}個`;
  }

  // エラー表示
  function showError(elementId, message) {
    const errorElement = container.querySelector(`#${elementId}`);
    if (errorElement) {
      errorElement.textContent = message;
    }
  }

  // エラークリア
  function clearError(elementId) {
    const errorElement = container.querySelector(`#${elementId}`);
    if (errorElement) {
      errorElement.textContent = '';
    }
  }

  function clearAllErrors() {
    const errorElements = container.querySelectorAll('.error-message');
    errorElements.forEach(el => el.textContent = '');
  }

  // 初期化
  loadStores();
  renderProducts(tables[2]?.records || []);

  // イベントリスナー
  container.querySelector('#btn-filter').addEventListener('click', filterProducts);
  container.querySelector('#btn-product-search').addEventListener('click', filterProducts);
  container.querySelector('#btn-ai-predict').addEventListener('click', executeAIPrediction);
  container.querySelector('#btn-calculate').addEventListener('click', calculateOrderQuantity);

  // 商品選択
  container.addEventListener('change', e => {
    if (e.target.classList.contains('product-radio')) {
      selectedProductId = e.target.value;
    }
  });

  // スライダー値表示更新
  container.querySelector('#weather-impact').addEventListener('input', e => {
    container.querySelector('#weather-value').textContent = `${e.target.value}%`;
  });

  container.querySelector('#event-impact').addEventListener('input', e => {
    container.querySelector('#event-value').textContent = `${e.target.value}%`;
  });

  // 入力値バリデーション
  container.querySelector('#current-stock').addEventListener('input', e => {
    if (e.target.value && parseInt(e.target.value) < 0) {
      showError('stock-error', '在庫数は0以上の値を入力してください');
    } else {
      clearError('stock-error');
    }
  });

  container.querySelector('#safety-stock').addEventListener('input', e => {
    if (isNaN(parseInt(e.target.value))) {
      showError('safety-error', '数値を入力してください');
    } else {
      clearError('safety-error');
    }
  });

  container.querySelector('#lead-time').addEventListener('input', e => {
    const value = parseInt(e.target.value);
    if (value && (value < 1 || value > 365)) {
      showError('leadtime-error', 'リードタイムは1-365日の範囲で入力してください');
    } else {
      clearError('leadtime-error');
    }
  });

  container.querySelector('#seasonal-factor').addEventListener('input', e => {
    const value = parseFloat(e.target.value);
    if (value && (value < 0.01 || value > 9.99)) {
      showError('seasonal-error', '季節補正係数は0.01-9.99の範囲で入力してください');
    } else {
      clearError('seasonal-error');
    }
  });

  container.querySelector('#manual-adjustment').addEventListener('input', e => {
    const value = parseInt(e.target.value);
    if (e.target.value && (isNaN(value) || value < 0)) {
      showError('manual-error', '発注量は0以上の値を入力してください');
    } else {
      clearError('manual-error');
    }
  });
}
